// Products is the resolver for the products field.
func (r *categoryResolver) Products(ctx context.Context, obj *models.Category) ([]*models.Product, error) {
	var productCategories []models.ProductCategory
	err := r.DB.Where("category_id = ?", obj.ID).Preload("Product").Find(&productCategories).Error
	if err != nil {
		return nil, err
	}

	products := make([]*models.Product, 0, len(productCategories))
	for _, pc := range productCategories {
		if pc.Product != nil {
			products = append(products, pc.Product)
		}
	}
	return products, nil
}

