	if search != nil && *search != "" {
		query = query.Where("categories.name ILIKE ?", "%"+*search+"%")
	}

	// Matches CategoryResolver.categories' `list` branch: an INNER JOIN
	// through product_categories to active products, one query — not a
	// COUNT per category (that was a real N+1 regression from the Node
	// version's single-query `include`, caught by benchmarking this
	// endpoint against the Node server side by side).
